SELECT su.uid AS id, su.user_name AS userName, su.real_name AS realName, su.mobile, su.code FROM sys_user_info su WHERE su.user_state = 1 AND su.is_deleted = false AND su.user_type='erp' AND
${params.sqlMap.default}
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
su.create_time desc

SELECT kup.id, kp.name AS postName, kd.kingdee_dept_name AS deptName, kup.use_org_name AS orgName, su.user_name AS userName FROM kingdee_user_ref_post kup LEFT JOIN kingdee_post kp ON kup.kingdee_post_id = kp.id AND kp.is_deleted = false LEFT JOIN kingdee_department kd ON kup.kingdee_department_id = kd.id AND kd.is_deleted = false LEFT JOIN sys_user_info su ON kup.erp_user_id = su.uid WHERE kup.is_deleted = false and su.is_deleted = false AND
${params.sqlMap.default}
${params.permissionSql}
ORDER BY kup.create_time desc
